def reverse_k_group(head, k):
    dummy = tail = ListNode()
    node = head
    while node:
        stack, probe = [], node
        while probe and len(stack) < k:
            stack.append(probe)
            probe = probe.next
        if len(stack) < k:
            tail.next = node                   # short tail group stays as is
            break
        while stack:
            tail.next = tail = stack.pop()
        tail.next = None
        node = probe
    return dummy.next

def reverse_k_group(head, k):
    node = head
    for _ in range(k):
        if node is None:
            return head                        # fewer than k: leave as is
        node = node.next
    prev, cur = reverse_k_group(node, k), head
    for _ in range(k):
        cur.next, prev, cur = prev, cur, cur.next
    return prev

def reverse_k_group(head, k):
    dummy = ListNode(0, head)
    group_prev = dummy
    while True:
        kth = group_prev
        for _ in range(k):
            kth = kth.next
            if kth is None:
                return dummy.next
        group_next = kth.next
        prev, cur = group_next, group_prev.next
        while cur is not group_next:
            cur.next, prev, cur = prev, cur, cur.next
        first = group_prev.next                # old first, now the group's tail
        group_prev.next = kth
        group_prev = first
